// ── Errors ──────────────────────────────────────────────────────────────────

#[derive(Debug, Error)]
pub enum KylinVectorDBError {
    #[error("libkysdk-vector-engine-client not found — install libkysdk-vector-engine-client-dev or set KART_VECTOR_DB_SDK_PATH")]
    LibraryNotFound,

    #[error("Failed to create vector database engine")]
    EngineCreateFailed,

    #[error("Engine connect failed (code {0})")]
    ConnectFailed(i32),

    #[error("Failed to load database file (code {0})")]
    LoadDbFailed(i32),

    #[error("Schema error: {0}")]
    SchemaError(String),

    #[error("Operation {op} failed (code {code})")]
    OpFailed { op: &'static str, code: i32 },

    #[error("Invalid input: {0}")]
    InvalidInput(String),

    #[error("SDK function not found in library: {0}")]
    FunctionNotFound(String),
}

pub type Result<T> = std::result::Result<T, KylinVectorDBError>;

// ── Enum wrappers for SDK magic numbers ─────────────────────────────────────

// SDK magic numbers from vectordataengine.h / demo.
// Task 1.0: header not installed on this machine; values from demo:
//   DataType: 5=INT64, 21=VARCHAR, 101=FLOAT_VECTOR, 104=SPARSE_VECTOR
//   FunctionType: 1=BM25
//   IndexType: 1=FLAT (dense), 1201=SPARSE_IVF_FLAT (sparse)
//   MetricType: 3=COSINE (dense), 201=SPARSE_IP (sparse)
// If the header defines named enums with different values, those take precedence.

/// Field data types understood by the SDK.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DataType {
    /// INT64 (SDK magic number 5)
    Int64 = 5,
    /// VARCHAR (SDK magic number 21)
    VarChar = 21,
    /// FLOAT_VECTOR (SDK magic number 101)
    FloatVector = 101,
    /// SPARSE_VECTOR (SDK magic number 104)
    SparseVector = 104,
}

/// Function types for collection-level functions.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FunctionType {
    /// BM25 text-to-sparse function (SDK magic number 1)
    Bm25 = 1,
}

/// Index types for create_index.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IndexType {
    /// FLAT index for dense vectors (SDK magic number 1)
    Flat = 1,
    /// IVF_FLAT index for dense vectors (SDK magic number 2)
    IvfFlat = 2,
    /// Sparse IVF_FLAT index for sparse vectors (SDK magic number 1201)
    SparseIvfFlat = 1201,
}

/// Metric types for index creation.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MetricType {
    /// L2 / Euclidean distance (SDK magic number 1)
    L2 = 1,
    /// Inner product (SDK magic number 2)
    Ip = 2,
    /// Cosine similarity (SDK magic number 3)
    Cosine = 3,
    /// Sparse inner product (SDK magic number 201)
    SparseIp = 201,
}

