    /// List all collections in the current database.
    pub fn show_collections(&self) -> Result<Vec<String>> {
        #[cfg(feature = "stub")]
        {
            Err(KylinVectorDBError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinVectorDBError::LibraryNotFound)?;

            let f: Symbol<
                unsafe extern "C" fn(
                    *mut VectorDataEngine,
                    *mut *mut *mut c_char,
                    *mut c_int,
                ) -> c_int,
            > = sym(lib, b"vector_data_engine_show_collections\0")?;

            let engine = self.inner.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("engine mutex poisoned".to_string())
            })?;

            let mut names_ptr: *mut *mut c_char = std::ptr::null_mut();
            let mut len: c_int = 0;
            let rc = unsafe { f(*engine, &mut names_ptr, &mut len) };
            if rc != 0 {
                return Err(KylinVectorDBError::OpFailed {
                    op: "show_collections",
                    code: rc,
                });
            }

            let mut result = Vec::with_capacity(len as usize);
            if !names_ptr.is_null() && len > 0 {
                let slice = unsafe { std::slice::from_raw_parts(names_ptr, len as usize) };
                for &ptr in slice {
                    if !ptr.is_null() {
                        let s = unsafe { CStr::from_ptr(ptr) }
                            .to_string_lossy()
                            .into_owned();
                        result.push(s);
                        libc_free(ptr as *mut _);
                    }
                }
                libc_free(names_ptr as *mut _);
            }
            Ok(result)
        }
    }

