    // ── Schema builders & create ─────────────────────────────────────────

    /// Create a collection from the given schema.
    pub fn create_collection(&self, schema: &CollectionSchemaBuilder) -> Result<()> {
        #[cfg(feature = "stub")]
        {
            let _ = schema;
            Err(KylinVectorDBError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinVectorDBError::LibraryNotFound)?;

            let f: Symbol<
                unsafe extern "C" fn(*mut VectorDataEngine, *mut CollectionSchema) -> c_int,
            > = sym(lib, b"vector_data_engine_create_collection\0")?;

            let engine = self.inner.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("engine mutex poisoned".to_string())
            })?;

            let raw = schema.raw.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("schema mutex poisoned".to_string())
            })?;

            let rc = unsafe { f(*engine, *raw) };
            if rc != 0 {
                return Err(KylinVectorDBError::OpFailed {
                    op: "create_collection",
                    code: rc,
                });
            }
            Ok(())
        }
    }

    /// Create an index on a collection field.
    pub fn create_index(
        &self,
        collection: &str,
        field: &str,
        index_name: &str,
        index_type: IndexType,
        metric_type: MetricType,
    ) -> Result<()> {
        #[cfg(feature = "stub")]
        {
            let _ = (collection, field, index_name, index_type, metric_type);
            Err(KylinVectorDBError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinVectorDBError::LibraryNotFound)?;

            let coll_cstr = CString::new(collection)
                .map_err(|e| KylinVectorDBError::InvalidInput(e.to_string()))?;
            let field_cstr =
                CString::new(field).map_err(|e| KylinVectorDBError::InvalidInput(e.to_string()))?;
            let idx_cstr = CString::new(index_name)
                .map_err(|e| KylinVectorDBError::InvalidInput(e.to_string()))?;

            let f: Symbol<
                unsafe extern "C" fn(
                    *mut VectorDataEngine,
                    *const c_char,
                    *const c_char,
                    *const c_char,
                    c_int,
                    c_int,
                ) -> c_int,
            > = sym(lib, b"vector_data_engine_create_index\0")?;

            let engine = self.inner.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("engine mutex poisoned".to_string())
            })?;

            let rc = unsafe {
                f(
                    *engine,
                    coll_cstr.as_ptr(),
                    field_cstr.as_ptr(),
                    idx_cstr.as_ptr(),
                    index_type as c_int,
                    metric_type as c_int,
                )
            };
            if rc != 0 {
                return Err(KylinVectorDBError::OpFailed {
                    op: "create_index",
                    code: rc,
                });
            }
            Ok(())
        }
    }

    // ── Insert ───────────────────────────────────────────────────────────

    /// Insert rows into a collection using columnar field data.
    ///
    /// Returns the number of rows inserted.
    pub fn insert(&self, collection: &str, fields: Vec<FieldData>) -> Result<usize> {
        #[cfg(feature = "stub")]
        {
            let _ = (collection, fields);
            Err(KylinVectorDBError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinVectorDBError::LibraryNotFound)?;

            let coll_cstr = CString::new(collection)
                .map_err(|e| KylinVectorDBError::InvalidInput(e.to_string()))?;

            let f: Symbol<
                unsafe extern "C" fn(
                    *mut VectorDataEngine,
                    *const c_char,
                    *mut *mut std::ffi::c_void,
                    c_int,
                    *mut c_int,
                ) -> c_int,
            > = sym(lib, b"vector_data_engine_insert\0")?;

            let engine = self.inner.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("engine mutex poisoned".to_string())
            })?;

            // Build columnar field data arrays. CStrings passed to SDK
            // `add_value` must outlive the `insert` call — keep them owned
            // here, not inside the per-field helpers.
            let mut field_ptrs: Vec<*mut std::ffi::c_void> = Vec::with_capacity(fields.len());
            let mut string_holders: Vec<Vec<CString>> = Vec::new();

            for fd in &fields {
                match fd {
                    FieldData::VarChar { name, values } => {
                        let (data, holder) = self.create_string_field_data(name, values, lib)?;
                        field_ptrs.push(data as *mut std::ffi::c_void);
                        string_holders.push(holder);
                    }
                    FieldData::Int64 { name, values } => {
                        let data = self.create_int64_field_data(name, values, lib)?;
                        field_ptrs.push(data as *mut std::ffi::c_void);
                    }
                    FieldData::FloatVec { name, dim, values } => {
                        let data = self.create_float_vec_field_data(name, *dim, values, lib)?;
                        field_ptrs.push(data as *mut std::ffi::c_void);
                    }
                }
            }

            let mut rows: c_int = 0;
            let rc = unsafe {
                f(
                    *engine,
                    coll_cstr.as_ptr(),
                    field_ptrs.as_mut_ptr(),
                    field_ptrs.len() as c_int,
                    &mut rows,
                )
            };

            // Clean up field data objects regardless of insert result.
            // `string_holders` lifetime ends here, after the SDK call returned —
            // by then the SDK has either copied the strings internally or
            // failed; in both cases the CString backing memory is safe to free.
            self.destroy_field_data(&field_ptrs, &fields, lib);
            drop(string_holders);

            if rc != 0 {
                return Err(KylinVectorDBError::OpFailed {
                    op: "insert",
                    code: rc,
                });
            }
            Ok(rows as usize)
        }
    }

    // ── Search ───────────────────────────────────────────────────────────

    /// Execute a single-vector search.
    pub fn search(&self, args: SearchArgumentsBuilder) -> Result<SearchResultsWrapper> {
        #[cfg(feature = "stub")]
        {
            let _ = args;
            Err(KylinVectorDBError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinVectorDBError::LibraryNotFound)?;

            let f: Symbol<
                unsafe extern "C" fn(
                    *mut VectorDataEngine,
                    *mut SearchArguments,
                    c_int,
                    *mut *mut SearchResults,
                ) -> c_int,
            > = sym(lib, b"vector_data_engine_search\0")?;

            let engine = self.inner.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("engine mutex poisoned".to_string())
            })?;

            let raw = args.raw.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("search args mutex poisoned".to_string())
            })?;

            let mut results_ptr: *mut SearchResults = std::ptr::null_mut();
            let rc = unsafe { f(*engine, *raw, 0, &mut results_ptr) };

            if rc != 0 {
                return Err(KylinVectorDBError::OpFailed {
                    op: "search",
                    code: rc,
                });
            }

            Ok(SearchResultsWrapper {
                raw: results_ptr,
                _lib: lib,
            })
        }
    }

    /// Execute a hybrid search with RRF ranker.
    pub fn hybrid_search_rrf(
        &self,
        collection: &str,
        anns: Vec<AnnSearchRequestBuilder>,
        ranker: RrfRankerBuilder,
        top_k: i32,
        output_fields: &[&str],
    ) -> Result<SearchResultsWrapper> {
        #[cfg(feature = "stub")]
        {
            let _ = (collection, anns, ranker, top_k, output_fields);
            Err(KylinVectorDBError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinVectorDBError::LibraryNotFound)?;

            let coll_cstr = CString::new(collection)
                .map_err(|e| KylinVectorDBError::InvalidInput(e.to_string()))?;

            let f: Symbol<
                unsafe extern "C" fn(
                    *mut VectorDataEngine,
                    *const c_char,
                    *mut *const AnnSearchRequest,
                    c_int,
                    *mut RRFRanker,
                    c_int,
                    *const *const c_char,
                    c_int,
                    c_int,
                    *mut *mut SearchResults,
                ) -> c_int,
            > = sym(lib, b"vector_data_engine_hybrid_search_rrf\0")?;

            let engine = self.inner.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("engine mutex poisoned".to_string())
            })?;

            // Collect raw AnnSearchRequest pointers
            let mut ann_ptrs: Vec<*const AnnSearchRequest> = Vec::with_capacity(anns.len());
            for ann in &anns {
                let raw = ann.raw.lock().map_err(|_| {
                    KylinVectorDBError::InvalidInput("ann mutex poisoned".to_string())
                })?;
                ann_ptrs.push(*raw);
            }

            // Get raw ranker
            let ranker_raw = ranker.raw.lock().map_err(|_| {
                KylinVectorDBError::InvalidInput("ranker mutex poisoned".to_string())
            })?;

            // Build output field C strings
            let output_cstrs: Vec<CString> = output_fields
                .iter()
                .map(|&s| {
                    CString::new(s).map_err(|e| KylinVectorDBError::InvalidInput(e.to_string()))
                })
                .collect::<Result<Vec<_>>>()?;
            let output_ptrs: Vec<*const c_char> = output_cstrs.iter().map(|c| c.as_ptr()).collect();

            let mut results_ptr: *mut SearchResults = std::ptr::null_mut();
            let rc = unsafe {
                f(
                    *engine,
                    coll_cstr.as_ptr(),
                    ann_ptrs.as_mut_ptr() as *mut *const AnnSearchRequest,
                    ann_ptrs.len() as c_int,
                    *ranker_raw,
                    top_k,
                    output_ptrs.as_ptr(),
                    output_ptrs.len() as c_int,
                    0,
                    &mut results_ptr,
                )
            };

            if rc != 0 {
                return Err(KylinVectorDBError::OpFailed {
                    op: "hybrid_search_rrf",
                    code: rc,
                });
            }

            Ok(SearchResultsWrapper {
                raw: results_ptr,
                _lib: lib,
            })
        }
    }

