// ── libc free helper ────────────────────────────────────────────────────────

/// Wrapper around libc free. The SDK allocates char** / float** / int64_t*
/// buffers with malloc, so they must be freed with free (not the SDK's
/// destroy functions).
#[cfg(not(feature = "stub"))]
fn libc_free(ptr: *mut std::ffi::c_void) {
    extern "C" {
        fn free(ptr: *mut std::ffi::c_void);
    }
    // SAFETY: ptr comes from the SDK's malloc'd result buffers.
    unsafe { free(ptr) };
}

// ── Tests ───────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn is_available_does_not_panic() {
        let _ = is_available();
    }

    #[test]
    fn error_display_library_not_found() {
        let e = KylinVectorDBError::LibraryNotFound;
        assert!(e.to_string().contains("libkysdk-vector-engine-client"));
    }

    #[test]
    fn error_display_connect_failed() {
        let e = KylinVectorDBError::ConnectFailed(-7);
        assert!(e.to_string().contains("-7"));
    }

    #[test]
    fn error_display_load_db_failed() {
        let e = KylinVectorDBError::LoadDbFailed(3);
        assert!(e.to_string().contains("3"));
    }

    #[test]
    fn error_display_op_failed() {
        let e = KylinVectorDBError::OpFailed {
            op: "insert",
            code: 42,
        };
        let s = e.to_string();
        assert!(s.contains("insert"));
        assert!(s.contains("42"));
    }

    #[test]
    fn error_display_invalid_input() {
        let e = KylinVectorDBError::InvalidInput("bad".into());
        assert!(e.to_string().contains("bad"));
    }

    #[test]
    fn error_display_function_not_found() {
        let e = KylinVectorDBError::FunctionNotFound("missing_fn".into());
        assert!(e.to_string().contains("missing_fn"));
    }

    #[test]
    fn error_display_schema_error() {
        let e = KylinVectorDBError::SchemaError("null pointer".into());
        assert!(e.to_string().contains("null pointer"));
    }

    #[test]
    fn data_type_values_match_demo_magic_numbers() {
        assert_eq!(DataType::Int64 as i32, 5);
        assert_eq!(DataType::VarChar as i32, 21);
        assert_eq!(DataType::FloatVector as i32, 101);
        assert_eq!(DataType::SparseVector as i32, 104);
    }

    #[test]
    fn function_type_values() {
        assert_eq!(FunctionType::Bm25 as i32, 1);
    }

    #[test]
    fn index_type_values() {
        assert_eq!(IndexType::Flat as i32, 1);
        assert_eq!(IndexType::IvfFlat as i32, 2);
        assert_eq!(IndexType::SparseIvfFlat as i32, 1201);
    }

    #[test]
    fn metric_type_values() {
        assert_eq!(MetricType::L2 as i32, 1);
        assert_eq!(MetricType::Ip as i32, 2);
        assert_eq!(MetricType::Cosine as i32, 3);
        assert_eq!(MetricType::SparseIp as i32, 201);
    }

    #[test]
    fn schema_builders_construct_and_drop_in_stub_mode() {
        // These should not panic even without SDK
        let field = FieldSchemaBuilder::new("test", DataType::Int64);
        assert!(field.is_ok());
        let func = FunctionSchemaBuilder::bm25("bm25_fn", "f_content", "f_sparse");
        assert!(func.is_ok());
        let schema = CollectionSchemaBuilder::new("test_coll", "desc", false);
        assert!(schema.is_ok());
    }
}
